class RetryStrategy(IntEnum):
    # Probe strategy constants
    FAIL = 0  # bad probes fail with a command error
    IGNORE = 1  # bad probes are ignored
    RETRY = 2  # bad probes are retried in the same location, assumes
    # no fouling
    CIRCLE = 3

